var o={feed:{label:"Feed",icon:"grid",kind:"post",dur:15,client:!0,best:["11:30","12:30","18:00","19:30"],tip:"Feed costuma ter mais alcance entre 11h\u201313h (almo\xE7o) e 18h\u201320h (sa\xEDda do trabalho).",placeholder:"Ex.: Post da promo\xE7\xE3o de ver\xE3o"},carrossel:{label:"Carrossel",icon:"layers",kind:"post",dur:15,client:!0,best:["11:30","12:30","18:30","20:00"],tip:"Carrossel prende aten\xE7\xE3o: publique quando o p\xFAblico tem tempo de deslizar \u2014 almo\xE7o ou noite.",placeholder:"Ex.: 5 dicas para\u2026"},reels:{label:"Reels",icon:"play",kind:"post",dur:15,client:!0,best:["12:00","18:00","19:00","20:30"],tip:"Reels: 12h e 18h\u201321h tendem a ter mais alcance. Evite publicar dois Reels da mesma empresa no mesmo dia.",placeholder:"Ex.: Bastidores da cozinha"},story:{label:"Story",icon:"story",kind:"post",dur:10,client:!0,best:["08:30","12:00","15:00","19:00","21:00"],tip:"Stories: distribua de 3 a 7 ao longo do dia (manh\xE3, almo\xE7o e noite) em vez de postar tudo de uma vez.",placeholder:"Ex.: Enquete sobre o novo sabor"},captacao:{label:"Capta\xE7\xE3o",icon:"camera",kind:"shoot",dur:120,client:!0,best:["08:30","09:00","16:00","16:30"],tip:"Capta\xE7\xE3o: a luz natural mais bonita \xE9 no in\xEDcio da manh\xE3 (8h\u201310h) e no fim da tarde (16h\u201317h30). Reserve 30\u201345 min de deslocamento.",placeholder:"Ex.: Fotos do card\xE1pio novo"},reuniao:{label:"Reuni\xE3o",icon:"users",kind:"meeting",dur:60,client:!0,best:["10:00","14:00","15:00"],tip:"Reuni\xF5es: prefira 10h ou 14h e deixe livres os hor\xE1rios de pico de postagem (12h e 18h\u201320h).",placeholder:"Ex.: Alinhamento do m\xEAs"},producao:{label:"Edi\xE7\xE3o",icon:"scissors",kind:"work",dur:90,client:!1,best:["09:00","10:00","14:00"],tip:"Edi\xE7\xE3o/produ\xE7\xE3o rende mais em blocos (batching): edite o conte\xFAdo da semana inteira de uma vez, de manh\xE3.",placeholder:"Ex.: Editar Reels da semana"},outro:{label:"Outro",icon:"dot",kind:"other",dur:30,client:!1,best:[],tip:"Use para tarefas avulsas: aprova\xE7\xE3o, or\xE7amento, pagamento, compras de material\u2026",placeholder:"Ex.: Enviar aprova\xE7\xE3o para o cliente"}},s=["feed","story","reels","carrossel","captacao","reuniao","producao","outro"],t=e=>o[e]?.kind==="post",r=e=>e.duration||o[e.type]?.dur||30,n={pendente:{label:"A fazer"},pronto:{label:"Pronto"},feito:{label:"Feito"}},i=["pendente","pronto","feito"],d=e=>{let a=t(e.type);return e.status==="feito"?a?"Publicado":"Realizado":e.status==="pronto"?a?"Agendado":"Confirmado":"Planejado"},l=["#16A34A","#0D9488","#0284C7","#2563EB","#4F46E5","#7C3AED","#C026D3","#DB2777","#E11D48","#EA580C","#CA8A04","#57534E"],p=[15,30,45,60,90,120,180,240,300,480],m=[{v:-1,label:"Sem lembrete"},{v:0,label:"Na hora"},{v:10,label:"10 min antes"},{v:15,label:"15 min antes"},{v:30,label:"30 min antes"},{v:60,label:"1 hora antes"},{v:120,label:"2 horas antes"},{v:1440,label:"1 dia antes"}],c=[{v:"none",label:"N\xE3o repetir"},{v:"daily",label:"Todo dia"},{v:"weekdays",label:"Dias \xFAteis (seg\u2013sex)"},{v:"weekly",label:"Toda semana"}],u=["Programe os posts no Meta Business Suite (ou no pr\xF3prio Instagram) na v\xE9spera. Assim, nenhum hor\xE1rio depende de voc\xEAs estarem com o celular na m\xE3o.","Fa\xE7a a capta\xE7\xE3o de v\xE1rios conte\xFAdos da mesma empresa numa visita s\xF3: fotos de feed, v\xEDdeos de Reels e material para stories.","Reserve um bloco fixo na semana (ex.: segunda de manh\xE3) para planejar a pauta de todas as empresas.","Nunca marquem uma capta\xE7\xE3o no mesmo hor\xE1rio de um post importante. Deixem o post programado antes de sair.","Entre duas capta\xE7\xF5es em lugares diferentes, deixem pelo menos 45 minutos livres para deslocamento e imprevistos.","Mandem o cronograma da semana para o cliente aprovar at\xE9 sexta-feira. Menos retrabalho, menos correria.","Depois de postar, fiquem 15\u201320 minutos respondendo coment\xE1rios: isso ajuda o alcance do post.","Agrupem tarefas parecidas: editar todos os Reels juntos, escrever todas as legendas juntas.","Antes de cada capta\xE7\xE3o: baterias carregadas, cart\xF5es de mem\xF3ria vazios, roteiro e lista de tomadas definidos.","Uma vez por m\xEAs, olhem os Insights de cada perfil e ajustem os hor\xE1rios. Cada p\xFAblico tem o seu pico.","Combinem quem responde o cliente em cada empresa. Um ponto de contato s\xF3 evita mensagens desencontradas.","Mantenham um banco de conte\xFAdo pronto (2 ou 3 posts reserva) por empresa para dias imprevis\xEDveis.","Evitem mais de 1 post de feed por dia na mesma empresa. Stories podem (e devem) ser v\xE1rios.","Mudan\xE7as de \xFAltima hora: atualizem o calend\xE1rio na hora, para o parceiro e o cliente verem a vers\xE3o certa."],h=[{type:"feed",text:"11h\u201313h \xB7 18h\u201320h"},{type:"reels",text:"12h \xB7 18h\u201321h"},{type:"story",text:"8h30 \xB7 12h \xB7 15h \xB7 19h \xB7 21h"},{type:"carrossel",text:"11h30\u201313h \xB7 18h30\u201320h"},{type:"captacao",text:"8h\u201310h \xB7 16h\u201317h30 (luz natural)"},{type:"reuniao",text:"10h \xB7 14h\u201315h"},{type:"producao",text:"Manh\xE3, em blocos"}];export{o as a,s as b,t as c,r as d,n as e,i as f,d as g,l as h,p as i,m as j,c as k,u as l,h as m};
